// ==========================================
// ⚙️ LUNAS WIRKUNG: GEISTERRUF (Zerzal)
// ==========================================

(async () => {
    // --- 1. SICHERHEITS-CHECK: FRAMEWORK LADEN ---
    if (typeof DSK === "undefined" || !globalThis.DSK) {
        const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
        if (fwMacro) await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150)); 
    }

    if (typeof DSK === "undefined" && !globalThis.DSK) {
        return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework konnte nicht geladen werden!");
    }
    const DSK_FW = globalThis.DSK || DSK; 

    const gabenName = "Geisterruf";
    const ahne = "Zerzal";
    const vollerName = `${gabenName} (${ahne})`;

    // --- 2. WIRKENDEN (CASTER) & QS AUS FLAG ERMITTELN ---
    const casterActor = canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!casterActor) {
        return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst den Token des Wirkenden aus!");
    }

    let casterToken = casterActor.getActiveTokens()[0] || canvas.tokens.controlled[0];
    if (!casterToken) {
        return ui.notifications.warn("Luna sagt 🌙: Konnte das Token des Wirkenden nicht finden!");
    }

    let qsWert = casterActor.getFlag("world", "letzteGabenQS") || 1;
    if (casterActor.getFlag("world", "letzteGabenQS")) {
        await casterActor.unsetFlag("world", "letzteGabenQS"); 
    }

    // Radius berechnen
    const radiusMeter = qsWert * 20;
    const casterName = DSK_FW.ResolveTokenName(casterActor);

    // --- 3. GEISTER IN REICHWEITE FINDEN ---
    const geister = canvas.tokens.placeables.filter(t => {
        if (t.id === casterToken.id) return false; // Caster ausschließen
        if (!t.actor) return false;

        const distMeter = DSK_FW.Distanz(casterToken, t);
        if (distMeter > radiusMeter) return false; // Zu weit weg

        return DSK_FW.Effekt.CheckTarget(t.actor, "geist"); // Ist es ein Geist?
    });

    // --- 4. GM-DIALOG ZUR AUSWAHL ---
    new Dialog({
        title: vollerName,
        content: `
        <div style="font-family: 'Signika', sans-serif;">
            ${DSK_FW.UI.Header(vollerName, DSK_FW.Symbol(ahne))}
            <div class="dskbox2" style="margin-top:10px;">
                <p style="margin-bottom:8px;">
                    <b>${casterName}</b> ruft in die Zwischenwelt (Radius: ${radiusMeter} Meter).<br>
                    Wen lockt der Ruf an?
                </p>
                <div style="background: rgba(0,0,0,0.05); padding: 8px; border-radius: 4px; max-height: 150px; overflow-y: auto;">
                    ${
                        geister.length === 0 
                        ? `<p style="color:#555; font-style:italic; margin:0;">Keine bekannten Geister auf der Map in Rufweite.</p>`
                        : geister.map(g => `
                            <div style="margin-bottom: 5px;">
                                <label style="cursor: pointer; display: flex; align-items: center; gap: 6px;">
                                    <input type="checkbox" name="geist" value="${g.id}">
                                    <span>${g.name}</span>
                                </label>
                            </div>
                        `).join("")
                    }
                </div>
                <hr style="margin:10px 0;">
                <div style="margin-bottom: 5px;">
                    <label style="cursor: pointer; display: flex; align-items: flex-start; gap: 6px;">
                        <input type="checkbox" name="neuerGeist" value="true" ${geister.length === 0 ? 'checked' : ''} style="margin-top:4px;">
                        <div>
                            <b>👻 Unbekannten Geist anlocken</b><br>
                            <span style="font-size: 0.85em; color: #555;">Wähle dies, wenn du einen neuen Token aus deinen Ordnern auf die Karte ziehen möchtest.</span>
                        </div>
                    </label>
                </div>
                <hr style="margin:10px 0;">
                <p style="font-size:0.85em; line-height:1.3; color:#444; margin:0;">
                    <i>Hinweis: Das Zerzalkind kann nicht bestimmen, wer antwortet. Wählst du mehrere Geister aus, bestimmt der Zufall, wer dem Ruf tatsächlich folgt. Die anderen Geister hören ihn nur.</i>
                </p>
            </div>
        </div>
        `,
        buttons: {
            ok: {
                label: "Ruf auslösen",
                callback: async (html) => {
                    const isNeuerGeist = html.find('input[name="neuerGeist"]').is(':checked');
                    const selectedIds = html.find('input[name="geist"]:checked').map((i, el) => el.value).get();

                    let reaktionsText = "";
                    let erfolg = true;

                    if (isNeuerGeist) {
                        // Der GM will einen neuen Geist spawnen
                        reaktionsText = `
                            Ein unbekannter Schemen formt sich an der Grenze der Wahrnehmung und nähert sich langsam.<br>
                            <span style="font-size: 0.85em; color: #555;">(Der Meister kann nun einen neuen Token auf die Karte ziehen)</span>
                        `;
                    } else if (selectedIds.length > 0) {
                        // Der GM hat Geister auf der Karte ausgewählt -> Zufall wählt EINEN aus
                        const geistId = selectedIds[Math.floor(Math.random() * selectedIds.length)];
                        const geistToken = canvas.tokens.get(geistId);

                        reaktionsText = `<b>${geistToken.name}</b> wurde von dem Ruf angelockt und begibt sich zur Quelle.`;
                    } else {
                        // Der GM hat NICHTS angekreuzt
                        erfolg = false;
                        reaktionsText = `Der Ruf verhallt ungehört im Äther. Kein Geist antwortet.`;
                    }

                    // --- 5. FINALE CHATKARTE ---
                    const contentHTML = `
                        ${DSK_FW.UI.Header(vollerName, DSK_FW.Symbol(ahne))}
                        <div class="dskbox2" style="margin-top:10px;">
                            <p style="font-size:0.95em; line-height:1.35;">
                                <b>${casterName}</b> ruft einen Geist aus der Zwischenwelt.<br><br>
                                • <b>Reichweite:</b> ${radiusMeter} Meter (QS ${qsWert})
                            </p>
                            <hr>
                            <div style="background: rgba(${erfolg ? '0,100,0' : '100,0,0'},0.05); padding: 8px; border-radius: 4px; border-left: 4px solid ${erfolg ? '#18940F' : '#B30000'}; font-style: italic; font-size: 0.95em;">
                                ${reaktionsText}
                            </div>
                            <hr>
                            <p style="font-weight:bold; margin-top:6px; text-align:center;">
                                Wirkungsdauer: sofort
                            </p>
                        </div>
                    `;

                    await ChatMessage.create({
                        content: contentHTML,
                        speaker: ChatMessage.getSpeaker({ actor: casterActor })
                    });
                }
            },
            cancel: { 
                label: "Abbrechen" 
            }
        },
        default: "ok",
        render: (html) => {
            const container = html instanceof jQuery ? html[0] : html;
            if (container) {
                const buttons = container.querySelectorAll('.dialog-button');
                buttons.forEach(btn => {
                    if (btn.textContent === "Abbrechen") {
                        btn.style.background = '#ddd';
                        btn.style.color = '#333';
                        btn.style.border = '1px solid #999';
                    } else {
                        btn.style.background = 'linear-gradient(#76301b,#582617)';
                        btn.style.color = '#f8f6f5';
                        btn.style.border = '1px solid #000';
                        btn.style.fontWeight = 'bold';
                    }
                });
            }
        }
    }).render(true);

})();
